import os,sys,json,hashlib
os.environ['OPENBLAS_NUM_THREADS']='1'
from pathlib import Path
P=Path(__file__).parent;O=P/'engineering-v16-results';sys.path.insert(0,str(P/'solver-libraries'));import numpy as np
def read_and_audit(path):
 r=json.loads(path.read_text());assert hashlib.sha256(Path(r['source']).read_bytes()).hexdigest()==r['source_sha256']
 with np.load(path.with_suffix('.npz')) as a:
  u=a['u'];force=a['force'];work=float(force@u.ravel());energy=abs(2*r['strain_energy_Nmm']-work)/abs(work);balance=float(np.linalg.norm(np.asarray(r['reaction_sum_N'])+force.reshape(-1,3).sum(axis=0)));fixed=float(np.max(np.abs(u.ravel()[a['fixed']])));finite=bool(np.isfinite(u).all() and np.isfinite(a['vm']).all())
 r['independent_algebra_audit']={'work_energy_relative_error':energy,'force_balance_error_N':balance,'maximum_fixed_displacement_mm':fixed,'pass':energy<1e-6 and balance<1e-6 and fixed<1e-12 and finite and r['relative_free_residual']<1e-6 and r['minimum_adaptive_Jacobian_mm3']>0};return r
meshes=[read_and_audit(O/('child_large_R16_tongue_guide82_h'+str(h)+'.json')) for h in [2.0,1.5]];a,b=meshes;dc=abs(b['weighted_load_direction_displacement_mm']/a['weighted_load_direction_displacement_mm']-1);sc=abs(b['max_von_mises_centroid_MPa']/a['max_von_mises_centroid_MPa']-1);top=read_and_audit(O/'child_large_R16_tongue_h2.0.json')
out={'fixture':'Child-large lower index plate, ideal rigid guide entrance z82','meshes':meshes,'displacement_mesh_change_fraction':dc,'sampled_peak_stress_mesh_change_fraction':sc,'mesh_comparison_pass':dc<.05 and sc<.05,'algebra_audits_pass':all(r['independent_algebra_audit']['pass'] for r in meshes),'alternative_top_only_fixture':top,'top_only_refinement':'1.5mm mesh and partial solve were interrupted after large deformation made refinement of this omitted-guide model a poor priority. No fine-mesh pass is claimed.','support_displacement_ratio':top['weighted_load_direction_displacement_mm']/b['weighted_load_direction_displacement_mm'],'limits':['Support conditions change the answer substantially; these are two ideal assumptions, not guaranteed bounds on the real headset','Top-only model predicts about11mm movement and is not a reliable small-displacement product prediction','Rigid-guide model truncates the stem and imposes a clamp; actual gaps friction screw preload headband compliance and bearing contact remain unresolved','No complete joint, drop, fatigue, physical or sensory validation']}
