ad=abs(adult[1]['weighted_load_direction_displacement_mm']/adult[0]['weighted_load_direction_displacement_mm']-1);ast=abs(adult[1]['max_von_mises_centroid_MPa']/adult[0]['max_von_mises_centroid_MPa']-1)
out['adult_upper_fixture']={'status':'Two mesh comparison passes chosen 5 percent gate' if ad<.05 and ast<.05 else 'Mesh comparison fails chosen gate','meshes':adult,'displacement_mesh_change_fraction':ad,'sampled_peak_stress_mesh_change_fraction':ast,'mesh_comparison_pass':ad<.05 and ast<.05,'algebra_audits_pass':all(r['independent_algebra_audit']['pass'] for r in adult),'failed_attempts':['Curved high-order optimizer aborted with ScaledJac error','Elastic optimizer left invalid curved elements and was rejected'],'limits':['Straight-sided quadratic elements approximate curved boundaries with facets','Only adult small upper tongue and neck; not the relocated fork or full joint','Ideal z82 rigid support, E2000MPa nu0.35 and10.833N whole-bore traction are assumed']}
